select #{finprodId,jdbcType=VARCHAR} as prodArray, #{valDateEnd} as endDate, #{valDateBegin} as startDate, t.report_name as reportName, count(t.report_name) as count, '01' as flag from( select ri.report_name, re.prod_id from REP_CHECK_ERRMSG re left join rep_info ri on re.rep_id=ri.rep_id where 1=1
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')<#{valDateEnd}
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')>#{valDateBegin}
AND re.prod_id IN
#{item}
) t group by t.report_name

select #{finprodId,jdbcType=VARCHAR} as prodArray, #{valDateEnd} as endDate, #{valDateBegin} as startDate, SUBSTRING(INDEX_ID,0,5) as reportName, count(INDEX_ID) as count, '02' as flag from REP_CHECK_ERRMSG where 1=1
and DATE_FORMAT(CREATE_TIME,'%Y-%m-%d')<#{valDateEnd}
and DATE_FORMAT(CREATE_TIME,'%Y-%m-%d')>#{valDateBegin}
AND prod_id IN
#{item}
group by INDEX_ID

select LIMIT as rId, ri.report_name reportName, case when re.START_DATE is null then DATE_FORMAT(re.END_DATE,'%Y-%m-%d') ELSE CONCAT_WS( '',DATE_FORMAT(re.START_DATE,'%Y-%m-%d'),'-',DATE_FORMAT(re.END_DATE,'%Y-%m-%d')) end reportDate, re.INDEX_ID indexId, re.INDEX_VALUE indexValue, re.PROD_ID prodId, re.PROD_NAME prodName, re.PROD_VALUE prodValue, re.ERRORMSG errormsg from REP_CHECK_ERRMSG re left join rep_info ri on re.rep_id=ri.rep_id where 1=1
and ri.report_name=#{reportName}
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')<#{endDate}
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')>#{startDate}
AND re.prod_id IN
#{item}

select LIMIT as rId, ri.report_name reportName, case when re.START_DATE is null then DATE_FORMAT(re.END_DATE,'%Y-%m-%d') ELSE CONCAT_WS( '',DATE_FORMAT(re.START_DATE,'%Y-%m-%d'),' - ',DATE_FORMAT(re.END_DATE,'%Y-%m-%d')) end reportDate, re.INDEX_ID indexId, re.INDEX_VALUE indexValue, re.PROD_ID prodId, re.PROD_NAME prodName, re.PROD_VALUE prodValue, re.ERRORMSG errormsg from REP_CHECK_ERRMSG re left join rep_info ri on re.rep_id=ri.rep_id where 1=1
and re.INDEX_ID=#{reportName}
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')<#{endDate}
and DATE_FORMAT(re.CREATE_TIME,'%Y-%m-%d')>#{startDate}
AND re.prod_id IN
#{item}

